query:
mutation($repositoryId:ID!, $title:String!, $body:String!,
         $headRef:String!, $baseRef:String!) {
  createPullRequest(input: {
    repositoryId: $repositoryId,
    title: $title,
    body: $body,
    headRefName: $headRef,
    baseRefName: $baseRef,
    maintainerCanModify: true
  }) {
    pullRequest { number url state title }
  }
}
